function trainingWeek(n){
 const phase=WEEKS[n-1], sat=SATURDAY[n-1], sun=SUNDAY[n-1];
 const easy=n===5||n===10||n===11;
 const mondayText= n===11?'Sehr leichtes CrossFit oder nur Mobilität; Metcon auslassen und keine schweren Bein-/Schulterserien.':easy?'CrossFit technisch, moderates Gewicht und Metcon RPE höchstens 5–6.':'CrossFit-Klasse wie gewohnt, aber Metcon RPE 6–7; zusätzliche harte Bein- oder Überkopfblöcke skalieren.';
 const wednesdayText= n===11?'20–30 min Aktivierung, Mobility und 3 × 3 lockere Wettkampfbewegungen; kein ermüdender WOD.':n===9?'CrossFit mit reduziertem Umfang (ca. 60 %); kein All-out vor der Generalprobe.':easy?'CrossFit locker, Technik/Zone 2 priorisieren; Volumen ungefähr halbieren.':'CrossFit wie gewohnt mit Tagesformsteuerung; keine Maximalversuche, Samstag bleibt die spezifische Schlüsseleinheit.';
 const sessions=[
  {day:'Montag',kind:'CrossFit',title:'CrossFit · Belastung steuern',goal:'Bestehendes CrossFit integrieren und die spezifische Wochenarbeit frisch absolvieren.',warm:'Klassen-Warm-up; bei Bedarf 5 min lockeres Ergometer und Hüft-/Schultermobilität.',work:mondayText,rest:'Klassenpausen; keine zusätzlichen Finisher.',rpe:n===11?'3–4':easy?'5–6':'6–7',duration:n===11?'20–35 min':'45–60 min',tech:'Spezifische Samstagsarbeit hat Vorrang. Coach über Trainingsphase und müde Beine informieren.',scale:'Metcon halbieren, Bein-/Überkopfvolumen reduzieren oder Technikklasse wählen.',cool:'5 min Gehen und leichtes Mobility.'},
  {day:'Mittwoch',kind:'CrossFit',title:'CrossFit · Qualität erhalten',goal:'Kraft und Fertigkeiten erhalten, ohne die Wochenbelastung unnötig zu häufen.',warm:'Klassen-Warm-up plus 2 × 10 Glute Bridge und Band Pull-apart.',work:wednesdayText,rest:'Pausen aus der Klasse; mindestens 60–90 s bei Zusatzarbeit.',rpe:n===11?'3–4':easy?'5–6':'6–7',duration:n===11?'20–30 min':'45–60 min',tech:'Keine Zusatztests am selben Tag. Bei müden Schultern Overhead-Anteile anpassen.',scale:'WOD auslassen und 25–35 min Zone 2 plus Technik durchführen.',cool:'5 min locker gehen/radeln, Atem beruhigen.'},
  {...sat,day:'Samstag',kind:'Team',title:`Team Session · Woche ${n}`,rpe:phase[2],tech:`${sat.tech} Beide bleiben während eines Pairs-Labours zusammen; Last nicht direkt übergeben, zum Wechsel sicher auf dem Boden ablegen.`,scale:sat.scale,cool:sat.cool},
  {day:'Sonntag',kind:'Run',title:'Laufen · gemeinsame Ökonomie',goal:'Aerobe Basis und ein gemeinsam steuerbares Tempo entwickeln.',warm:'5 min gehen, 5 min sehr locker traben; Sprunggelenk-/Hüftmobilität.',work:sun.work,rest:'Steigerungen mit vollständiger lockerer Erholung.',rpe:sun.rpe,duration:sun.duration,tech:'Laufabschnitte immer gemeinsam; Tempo richtet sich nach der Athletin mit dem geringeren Tagesvermögen.',scale:n===11?'Kein Lauf; Ruhetag.':'Auf 20 min Walk-run kürzen oder bei Beschwerden auslassen.',cool:'5 min gehen, Waden/Hüftbeuger sanft mobilisieren.'}
 ];
 if(n===11)sessions.pop();
 return sessions;
}
const base = {version:2,trainingPlanVersion:2,athletes:[{name:'Kerstin',color:'#e9f04b'},{name:'Trainingspartnerin',color:'#73a7ff'}],teamName:'Road to Race',activeAthlete:0,schedule:['Montag','Dienstag','Mittwoch','Donnerstag','Freitag','Samstag','Sonntag'],customWorkouts:[],moves:{},logs:[],tests:[],runs:[],simulations:[],deleted:[],settingsUpdatedAt:0,race:{splits:[],targetSeconds:null,pacing:'',notes:'',checklist:{},strategies:{}},status:'local'};
function load(){try{const old=JSON.parse(localStorage.getItem('ddrz-data')||'{}'),next={...structuredClone(base),...old};next.race={...base.race,...(old.race||{}),strategies:old.race?.strategies||{}};for(const key of ['athletes','customWorkouts','logs','tests','runs','simulations','deleted'])if(!Array.isArray(next[key]))next[key]=structuredClone(base[key]);next.moves=next.moves||{};next.version=2;next.trainingPlanVersion=2;return next}catch{return structuredClone(base)}}
let db=load(), tab='home', selectedWeek=1, timer=null, stopwatch={startedAt:null,elapsed:0}, raceTimer=null, wake=null;
